-- ========================================================================================
-- ZOOGUIDE - DEVICE ACTIVITIES SCHEMA ALIGNMENT MIGRATION
-- Migration: 20261027_Align_Device_Activities_Schema.sql
-- Description: Ensures DEVICE_ACTIVITIES table, columns, and indexes match the EF Core
--              domain model for truthful visitor device tracking & heartbeat monitoring.
-- ========================================================================================

CREATE TABLE IF NOT EXISTS public."DEVICE_ACTIVITIES" (
    "DeviceActivityId" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "InstallationId" VARCHAR(64) NOT NULL,
    "FirstSeenAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "LastSeenAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "UserAgent" VARCHAR(255) NULL,
    "IpAddressHash" VARCHAR(64) NULL,
    "HeartbeatCount" INTEGER NOT NULL DEFAULT 1,
    "CreatedAt" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "UpdatedAt" TIMESTAMPTZ NULL,
    "IsActive" BOOLEAN NOT NULL DEFAULT TRUE,
    "DisconnectedAt" TIMESTAMPTZ NULL,
    CONSTRAINT "PK_DEVICE_ACTIVITIES" PRIMARY KEY ("DeviceActivityId")
);

-- Unique constraint ensuring pseudonymous installation IDs are not duplicated
CREATE UNIQUE INDEX IF NOT EXISTS "UQ_DeviceActivities_InstallationId" 
ON public."DEVICE_ACTIVITIES" ("InstallationId");

-- Index for fast threshold queries (e.g. active within 60 seconds)
CREATE INDEX IF NOT EXISTS "IX_DeviceActivities_LastSeenAt" 
ON public."DEVICE_ACTIVITIES" ("LastSeenAt");

-- Composite index for active status and heartbeat recency
CREATE INDEX IF NOT EXISTS "IX_DeviceActivities_IsActive_LastSeenAt" 
ON public."DEVICE_ACTIVITIES" ("IsActive", "LastSeenAt");
